#!/usr/bin/env node
/**
 * Inlines browser libraries into TypeScript modules so the WebViews that host
 * them work offline, without loading scripts from a CDN:
 *   - pdf.js (PDF rendering)          -> src/lib/pdf-renderer/pdfjs-source.generated.ts
 *   - mammoth + docx (Word documents) -> src/lib/word/word-source.generated.ts
 * Runs automatically on `npm install` (postinstall).
 */

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');

function read(file) {
  // Escape closing script tags so the source can be embedded in an inline <script>.
  return fs
    .readFileSync(path.join(root, 'node_modules', file), 'utf8')
    .replace(/<\/script/gi, '<\\/script');
}

function writeModule(outPath, exports) {
  const outFile = path.join(root, outPath);
  const body = Object.entries(exports)
    .map(([name, file]) => `export const ${name} = ${JSON.stringify(read(file))};`)
    .join('\n');
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  fs.writeFileSync(outFile, `// AUTO-GENERATED by scripts/bundle-web-libs.js. Do not edit.\n${body}\n`);
  console.log(`bundled ${Object.keys(exports).join(', ')} into ${outPath}`);
}

writeModule('src/lib/pdf-renderer/pdfjs-source.generated.ts', {
  PDFJS_LIB: 'pdfjs-dist/build/pdf.min.js',
  PDFJS_WORKER: 'pdfjs-dist/build/pdf.worker.min.js',
});

writeModule('src/lib/word/word-source.generated.ts', {
  MAMMOTH_LIB: 'mammoth/mammoth.browser.min.js',
  DOCX_LIB: 'docx/build/index.iife.js',
});
